import { _ as user, h as roles, t as db } from "../../../../../../chunks/db.js";
import { r as APIError, t as auth } from "../../../../../../chunks/auth.js";
import "../../../../../../chunks/dist2.js";
import { i as superValidate, n as message } from "../../../../../../chunks/client2.js";
import { t as zod } from "../../../../../../chunks/adapters.js";
import { t as add } from "../../../../../../chunks/schema6.js";
import "../../../../../../chunks/dist3.js";
import { eq } from "drizzle-orm";
//#region src/routes/dashboard/admin-panel/users/add-users/+page.server.ts
var load = async () => {
	return {
		form: await superValidate(zod(add)),
		allRoles: await db.select({
			value: roles.id,
			name: roles.name
		}).from(roles)
	};
};
var actions = { add: async (event) => {
	const form = await superValidate(event.request, zod(add));
	console.log(form);
	if (!form.valid) return message(form, {
		type: "error",
		text: "Please Check the form}"
	}, { status: 500 });
	const { name, email, password, role } = form.data;
	try {
		await db.transaction(async (tx) => {
			const newCustomer = await auth.api.createUser({ body: {
				email,
				password,
				name,
				role: role === 1 ? "admin" : "user"
			} });
			await tx.update(user).set({ roleId: 1 }).where(eq(user.id, newCustomer?.user.id));
		});
		return message(form, {
			type: "success",
			text: "User Added Successful!"
		});
	} catch (error) {
		console.error(error);
		if (error instanceof APIError) return message(form, {
			type: "error",
			text: error?.message
		}, { status: 500 });
		return message(form, {
			type: "error",
			text: "Registration Failed" + error?.message
		}, { status: 500 });
	}
} };
//#endregion
export { actions, load };
